window.__votdWeek && window.__votdWeek({"week":"2027-09-06","reading":"2 Corinthians 1–7","days":[{"d":"2027-09-06","ref":"2 Corinthians 3:3","b":"2 Corinthians","c":3,"v":3,"he":"כִּי בְיָדוּעַ שֶׁאַתֶּם אִגֶּרֶת הַמָּשִׁיחַ עֲרוּכָה עַל־יְדֵי שֵׁרוּתֵנוּ כְּתוּבָה לֹא בִדְיוֹ כִּי אִם בְּרוּחַ אֱלֹהִים חַיִּים וְלֹא עַל־לוּחוֹת אֶבֶן כִּי אִם־עַל־לוּחוֹת בָּשָׂר לוּחוֹת הַלֵּב׃","en":"Forasmuch as ye are manifestly declared to be the epistle of Christ ministered by us, written not with ink, but with the Spirit of the living God; not in tables of stone, but in fleshy tables of the heart."},{"d":"2027-09-07","ref":"2 Corinthians 3:17","b":"2 Corinthians","c":3,"v":17,"he":"הָאָדוֹן הוּא הָרוּחַ וּבַאֲשֶׁר רוּחַ הָאָדוֹן שָׁם חֵרוּת׃","en":"Now the Lord is that Spirit: and where the Spirit of the Lord is, there is liberty."},{"d":"2027-09-08","ref":"2 Corinthians 4:4","b":"2 Corinthians","c":4,"v":4,"he":"אֲשֶׁר אֵל הָעוֹלָם הַזֶּה עִוֵּר בָּהֶם אֶת־מַחְשְׁבוֹת חַסְרֵי הָאֱמוּנָה לְבִלְתִּי זְרֹחַ לָהֶם נֹגַהּ בְּשׂוֹרַת כְּבוֹד הַמָּשִׁיחַ אֲשֶׁר הוּא צֶלֶם הָאֱלֹהִים׃","en":"In whom the god of this world hath blinded the minds of them which believe not, lest the light of the glorious gospel of Christ, who is the image of God, should shine unto them."},{"d":"2027-09-09","ref":"2 Corinthians 4:16","b":"2 Corinthians","c":4,"v":16,"he":"עַל־כֵּן לֹא נֵחָת וְאַף אִם־יִכְלֶה בָנוּ הָאָדָם הַחִיצוֹן הִנֵּה הָאָדָם הַפְּנִימִי יִתְחַדֵּשׁ יוֹם יוֹם׃","en":"For which cause we faint not; but though our outward man perish, yet the inward man is renewed day by day."},{"d":"2027-09-10","ref":"2 Corinthians 5:17","b":"2 Corinthians","c":5,"v":17,"he":"לָכֵן מִי שֶׁהוּא בַמָּשִׁיחַ בְּרִיָּה חֲדָשָׁה הוּא הָרִאשֹׁנוֹת עָבָרוּ הִנֵּה הַכֹּל נַעֲשׂוּ חֲדָשׁוֹת׃","en":"Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new."},{"d":"2027-09-11","ref":"2 Corinthians 6:17","b":"2 Corinthians","c":6,"v":17,"he":"עַל־כֵּן צְאוּ מִתּוֹכָם וְהִבָּרוּ נְאֻם־יְהוָֹה וְטָמֵא אַל־תִּגָּעוּ וַאֲנִי אֲקַבֵּץ אֶתְכֶם׃","en":"Wherefore come out from among them, and be ye separate, saith the Lord, and touch not the unclean thing; and I will receive you,"},{"d":"2027-09-12","ref":"2 Corinthians 7:10","b":"2 Corinthians","c":7,"v":10,"he":"כִּי הָעַצֶּבֶת שֶׁהִיא כִּרְצוֹן אֱלֹהִים גֹּרֶמֶת תְּשׁוּבָה לִישׁוּעָה אֲשֶׁר אִישׁ לֹא יִתְחָרֵט עָלֶיהָ וְעַצְּבַת הָעוֹלָם מְבִיאָה לִידֵי מִיתָה׃","en":"For godly sorrow worketh repentance to salvation not to be repented of: but the sorrow of the world worketh death."}]});
